#!/usr/bin/env python3
"""Lossless, stdlib-only compressor with a compact encoding for the corpus format."""
import bz2
import lzma
import re
import sys
import zlib

HEADER = re.compile(rb'e18a line ([0-9]+) ratio 0\.([0-9]{6}) select pick win seed ([0-9]+)\Z')
ALPHABET = b'0123456789abcdefghijklmnopqrstuvwxyz'


def encode(data):
    lines = data.splitlines(keepends=True)
    packed = bytearray()
    try:
        if not lines or any(not line.endswith(b'\n') for line in lines):
            raise ValueError('nonstandard line ending')
        for line in lines:
            line = line[:-1]
            match = HEADER.fullmatch(line)
            if match:
                first, fraction, seed = map(int, match.groups())
                if first >= 1 << 24 or seed >= 1 << 32:
                    raise ValueError('oversized header')
                packed.append(0)
                packed += first.to_bytes(3, 'big') + fraction.to_bytes(3, 'big') + seed.to_bytes(4, 'big')
            elif len(line) == 96 and all(ch in b'0123456789abcdef' for ch in line):
                packed.append(1)
                packed += bytes.fromhex(line.decode('ascii'))
            elif len(line) == 64 and all(ch in ALPHABET for ch in line):
                packed.append(2)
                n = int(line, 36)
                packed += n.to_bytes(42, 'big')
            else:
                raise ValueError('unrecognized line')
        raw = b'S' + bytes(packed)
    except ValueError:
        raw = b'R' + data
    choices = [(b'z', zlib.compress(raw, 9)), (b'b', bz2.compress(raw, 9)),
               (b'l', lzma.compress(raw, preset=9))]
    kind, output = min(choices, key=lambda choice: len(choice[1]))
    return b'CP1' + kind + output


def decode(data):
    if data[:3] != b'CP1':
        raise ValueError('not a compressed file')
    mode = data[3:4]
    if mode == b'z':
        raw = zlib.decompress(data[4:])
    elif mode == b'b':
        raw = bz2.decompress(data[4:])
    elif mode == b'l':
        raw = lzma.decompress(data[4:])
    else:
        raise ValueError('unknown compression method')
    if raw[:1] == b'R':
        return raw[1:]
    if raw[:1] != b'S':
        raise ValueError('unknown encoding')
    result = bytearray()
    p = 1
    while p < len(raw):
        tag = raw[p]
        p += 1
        length = {0: 10, 1: 48, 2: 42}.get(tag)
        if length is None or p + length > len(raw):
            raise ValueError('corrupt record')
        record = raw[p:p+length]
        p += length
        if tag == 0:
            first = int.from_bytes(record[:3], 'big')
            fraction = int.from_bytes(record[3:6], 'big')
            seed = int.from_bytes(record[6:], 'big')
            result += f'e18a line {first} ratio 0.{fraction:06d} select pick win seed {seed}\n'.encode()
        elif tag == 1:
            result += record.hex().encode() + b'\n'
        else:
            n = int.from_bytes(record, 'big')
            digits = bytearray(64)
            for i in range(63, -1, -1):
                n, d = divmod(n, 36)
                digits[i] = ALPHABET[d]
            if n:
                raise ValueError('base36 overflow')
            result += digits + b'\n'
    return bytes(result)


def main():
    if len(sys.argv) == 3:
        source, dest = sys.argv[1:]
        transform = encode
    elif len(sys.argv) == 4 and sys.argv[1] == '--decompress':
        source, dest = sys.argv[2:]
        transform = decode
    else:
        raise SystemExit('usage: compress.py [--decompress] INPUT OUTPUT')
    with open(source, 'rb') as f:
        data = f.read()
    result = transform(data)
    with open(dest, 'wb') as f:
        f.write(result)


if __name__ == '__main__':
    main()

