"""Prefix-coded record tags and bit-packed values."""
WIDTHS = (70, 384, 331)

def pack(values):
    buffer = 0
    bits = 0
    result = bytearray()
    def add(value, width):
        nonlocal buffer, bits
        buffer = buffer << width | value
        bits += width
        while bits >= 8:
            bits -= 8
            result.append(buffer >> bits & 255)
            buffer &= (1 << bits) - 1
    for tag, value in values:
        width = WIDTHS[tag]
        if value >= 1 << width:
            raise ValueError('record too large')
        if tag == 0:
            add(0, 1)
        else:
            add(tag + 1, 2)  # hex: 10, base36: 11
        add(value, width)
    if bits:
        result.append(buffer << (8 - bits))
    return bytes(result)

def unpack(data, count):
    buffer = 0
    bits = 0
    pos = 0
    def get(width):
        nonlocal buffer, bits, pos
        while bits < width:
            if pos >= len(data):
                raise ValueError('truncated record')
            buffer = buffer << 8 | data[pos]
            pos += 1
            bits += 8
        bits -= width
        value = buffer >> bits
        buffer &= (1 << bits) - 1
        return value
